import React from "react";
import { useCart } from "../context/CartContext";
import "./Header.css";

export default function Header() {
  const { totalCount, openCart } = useCart();

  return (
    <header className="header">
      <div className="header__inner">
        <a href="/" className="header__brand" aria-label="Gifted — início">
          <span className="header__mark" aria-hidden="true">
            <svg width="22" height="22" viewBox="0 0 22 22" fill="none">
              <rect width="22" height="22" rx="11" fill="#f5c4d3" />
              <path
                d="M11 5.5C9.6 5.5 8.5 6.6 8.5 8c0 .55.18 1.06.48 1.47L6 9.5v1.5h1v6h8v-6h1V9.5l-2.98-.03A2.5 2.5 0 0 0 13.5 8c0-1.4-1.1-2.5-2.5-2.5Zm0 1.5c.55 0 1 .45 1 1s-.45 1-1 1-1-.45-1-1 .45-1 1-1ZM7.5 11h3v4.5h-3V11Zm4 0h3v4.5h-3V11Z"
                fill="#c2567a"
              />
            </svg>
          </span>
          <span className="header__wordmark">Gifted</span>
        </a>

        {/* Cart button */}
        <button
          className="header__cart-btn"
          onClick={openCart}
          aria-label={`Abrir carrinho — ${totalCount} ${totalCount === 1 ? "item" : "itens"}`}
        >
          <svg width="22" height="22" viewBox="0 0 22 22" fill="none" aria-hidden="true">
            <path d="M3 3h2l.8 4M7 13h9l2-7H5.8" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/>
            <circle cx="9" cy="17" r="1.3" fill="currentColor"/>
            <circle cx="16" cy="17" r="1.3" fill="currentColor"/>
          </svg>
          {totalCount > 0 && (
            <span className="header__cart-badge" aria-hidden="true">
              {totalCount > 99 ? "99+" : totalCount}
            </span>
          )}
        </button>
      </div>
    </header>
  );
}
